/// <summary>
/// The <c>METPurchaseOrderInvoicedBusinessEventContract</c> class extends <c>BusinessEventsContract</c> to provide data contract for purchase order confirmed business event.
/// Task 305538: PB033 -CB492 - PO status 'Invoiced is not appearing in Abbyy Open PO table (Bug - 290169) - D365 Build
/// </summary>
[DataContract]
public final class METPurchaseOrderInvoicedBusinessEventContract extends BusinessEventsContract
{
    private LegalEntityDataAreaId       legalEntity;             
    private PurchIdBase                 purchaseOrderNumber;
    private VendAccount                 vendorAccount;
    private JournalId                   journalId;
    private InvoiceId                   invoiceId;
    private TransDate                   documentDate;
    private str                         purchaseType;
    private str                         requesterPersonnelNumber;
    private str                         requesterName;
    private str                         workerPurchPlacerPersonnelNumber;
    private str                         workerPurchPlacerName;
    private ContactPersonId             contactPersonId;
    private EmailBase                   email;
    private Phone                       phone;
    private ModifiedDateTime            modifiedDateTime;
    private METMultiSelectStringValue   poChngSubMode;
    private METMultiSelectStringValue   poSubMode;

}

